using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;
public static class PlantMotionChecks {
 [Serializable]class Model{public string id;public float[] world,touch;}[Serializable]class Fixture{public float[] matrix,direction;public float time,strength;public Model[] models;}
 [Serializable]class Check{public string name,status,detail;}[Serializable]class Report{public string status,unityVersion;public Check[] checks;}
 static List<Check> checks=new List<Check>();static void Verify(string name,bool ok,string detail=""){checks.Add(new Check{name=name,status=ok?"Passed":"Failed",detail=detail});if(!ok)throw new Exception(name+": "+detail);}static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 public static void Run(){string output=Arg("-nature-output"),export=Arg("-nature-export");int code=0;try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var lib=MapSharedPropsBuilder.ReadLibrary(Path.Combine(export,"shared_props.json"));var built=MapSharedPropsBuilder.Build(export);Verify("19 shared assets and 10 placements",built.prefabs.Count==19&&built.placed==10&&built.skipped==0);var manager=built.root.GetComponent<SharedPlantContact>();Verify("Ten contact entries registered",manager&&manager.entries.Count==10);
  var fixture=JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.Combine(output,"motion-probe-expected.json")));var matrix=new Matrix4x4();for(int r=0;r<4;r++)for(int c=0;c<4;c++)matrix[r,c]=fixture.matrix[c*4+r];
  foreach(var a in lib.assets){var o=built.prefabs[a.id];var mesh=o.GetComponent<MeshFilter>().sharedMesh;var p=mesh.vertices;var normal=mesh.normals;var uv=mesh.uv;float error=0;for(int i=0;i<p.Length;i++)error=Mathf.Max(error,Vector3.Distance(p[i],new Vector3(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2])),Vector3.Distance(normal[i],new Vector3(a.normals[i*3],a.normals[i*3+1],a.normals[i*3+2])),Vector2.Distance(uv[i],new Vector2(a.uv[i*2],a.uv[i*2+1])));Verify(a.id+" canonical geometry preserved",error<.000001f);
   if(a.motionWeights==null)continue;var mask=mesh.uv2;float maskError=0;for(int i=0;i<p.Length;i++)maskError=Mathf.Max(maskError,Mathf.Abs(mask[i].x-a.motionWeights[i*2]),Mathf.Abs(mask[i].y-a.motionWeights[i*2+1]));var material=o.GetComponent<Renderer>().sharedMaterial;Verify(a.id+" two GPU weights and mode",maskError<.000001f&&material.GetVector("_PineBand").w==3&&o.GetComponent<Renderer>().sharedMaterials.Length==1);Probe(a,mesh,material,matrix,fixture,Array.Find(fixture.models,m=>m.id==a.id));
  }
  var gale=JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.Combine(output,"gale-probe-expected.json")));var galeMatrix=Matrix4x4.identity;foreach(var expected in gale.models){var a=Array.Find(lib.assets,v=>v.id==expected.id);var prefab=built.prefabs[a.id];Probe(a,prefab.GetComponent<MeshFilter>().sharedMesh,prefab.GetComponent<Renderer>().sharedMaterial,galeMatrix,gale,expected);}
  var actor=new GameObject("Preview actor feet");var source=actor.AddComponent<SharedPlantContactSource>();source.height=1.8f;source.radius=.3f;manager.source=source;manager.useClock=false;
  foreach(var e in manager.entries){Vector3 origin=e.renderer.transform.position;actor.transform.position=origin+new Vector3(-2,0,.1f);manager.Step(.016f);float peak=0;for(int k=0;k<180;k++){actor.transform.position=origin+new Vector3(-2+k*.025f,0,.1f);manager.Step(1/60f);peak=Mathf.Max(peak,e.bend.magnitude);}bool tree=e.minY>2;Verify(e.renderer.name+" height aware actor passage",tree?peak==0:peak>0,"peak="+peak);
   actor.transform.position=origin+new Vector3(-.25f,0,.12f);float max=0;for(int k=0;k<1200;k++){manager.Step(1/60f);max=Mathf.Max(max,e.bend.magnitude);}Verify(e.renderer.name+" continuous contact remains bounded",max<=e.limit+.00001f,"max="+max+", limit="+e.limit);actor.transform.position=new Vector3(500,0,500);for(int k=0;k<360;k++)manager.Step(1/60f);Verify(e.renderer.name+" returns exactly to rest",e.bend==Vector2.zero&&e.velocity==Vector2.zero);
   var mesh=e.renderer.GetComponent<MeshFilter>().sharedMesh;var b=e.renderer.localBounds;float pad=e.renderer.sharedMaterial.GetVector("_PineBand").z+e.maxDisplacement;Verify(e.renderer.name+" conservative moving bounds",b.extents.x>=mesh.bounds.extents.x&&b.extents.z>=mesh.bounds.extents.z&&pad>0);
  }
  UnityEngine.Object.DestroyImmediate(built.root);var legacy=MapSharedPropsBuilder.Build(Path.Combine(output,"legacy-v2-export"));Verify("Previous 19-asset static export imports",legacy.prefabs.Count==19&&legacy.placed==10);Verify("Version one wind retains legacy response",legacy.prefabs["pine"].GetComponent<Renderer>().sharedMaterial.GetVector("_PineResponse").w==0);UnityEngine.Object.DestroyImmediate(legacy.root);
  // Real URP draws use the same imported UV2 and forward/shadow displacement.
  var floor=new GameObject("Shadow floor");floor.AddComponent<MeshFilter>().sharedMesh=new Mesh{vertices=new[]{new Vector3(-30,0,-30),new Vector3(-30,0,30),new Vector3(30,0,30),new Vector3(30,0,-30)},triangles=new[]{0,1,2,0,2,3},normals=new[]{Vector3.up,Vector3.up,Vector3.up,Vector3.up}};var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.SetColor("_BaseColor",new Color(.55f,.61f,.46f));floor.AddComponent<MeshRenderer>().sharedMaterial=fm;var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(3,-8,5));
  var camera=new GameObject("Motion proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.orthographic=true;camera.orthographicSize=2.2f;camera.aspect=1.6f;camera.transform.position=new Vector3(0,10,0);camera.transform.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);camera.backgroundColor=new Color(.55f,.61f,.46f);camera.clearFlags=CameraClearFlags.SolidColor;
  foreach(var id in new[]{"willow","sedge","ivy"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);o.transform.position=Vector3.zero;camera.orthographicSize=id=="willow"?4:1.1f;Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);Capture(camera,output,"unity-"+id+"-warmup.png");foreach(float time in new[]{0f,.7f}){Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,.85f,time));Capture(camera,output,"unity-"+id+"-wind-"+time.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+".png");}UnityEngine.Object.DestroyImmediate(o);}
  var messages=ShaderUtil.GetShaderMessages(Shader.Find("MapSharedProps/Lit"));bool valid=true;foreach(var msg in messages)if(msg.severity.ToString()=="Error")valid=false;Verify("Forward and shadow shader compile",valid);GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;
 }catch(Exception e){code=1;checks.Add(new Check{name="Unexpected failure",status="Failed",detail=e.ToString()});Debug.LogException(e);}File.WriteAllText(Path.Combine(output,"motion-unity.json"),JsonUtility.ToJson(new Report{status=code==0?"Passed":"Failed",unityVersion=Application.unityVersion,checks=checks.ToArray()},true));EditorApplication.Exit(code);}
 static void Probe(MapSharedPropsBuilder.AssetDto a,Mesh mesh,Material material,Matrix4x4 matrix,Fixture fixture,Model expected){int n=mesh.vertexCount;var positions=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);var masks=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);positions.filterMode=masks.filterMode=FilterMode.Point;var p=new Color[n];var w=new Color[n];for(int i=0;i<n;i++){p[i]=new Color(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2],a.uv[i*2+1]);w[i]=a.motionWeights!=null?new Color(a.motionWeights[i*2],a.motionWeights[i*2+1],0,0):Color.clear;}positions.SetPixels(p);positions.Apply();masks.SetPixels(w);masks.Apply();var probe=new Material(Shader.Find("Hidden/MapSharedProps/PlantMotionProbe"));probe.SetTexture("_Masks",masks);probe.SetMatrix("_ProbeMatrix",matrix);probe.SetVector("_PineBand",material.GetVector("_PineBand"));probe.SetVector("_PineWaves",material.GetVector("_PineWaves"));probe.SetVector("_PinePhase",material.GetVector("_PinePhase"));probe.SetVector("_PineResponse",material.GetVector("_PineResponse"));probe.SetVector("_PlantTouch",new Vector4(expected.touch[0],expected.touch[1],0,0));Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);Shader.SetGlobalVector("_TDPineWind",new Vector4(fixture.direction[0],fixture.direction[1],fixture.strength,fixture.time));var rt=new RenderTexture(n,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(positions,rt,probe);var previous=RenderTexture.active;RenderTexture.active=rt;var read=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,n,1),0,0);read.Apply();var pixels=read.GetPixels();float error=0,rootError=0;for(int i=0;i<n;i++){var want=new Vector3(expected.world[i*3],expected.world[i*3+1],expected.world[i*3+2]);var actual=new Vector3(pixels[i].r,pixels[i].g,pixels[i].b);error=Mathf.Max(error,Vector3.Distance(want,actual));if(IsFixed(a,material,i))rootError=Mathf.Max(rootError,Vector3.Distance(actual,matrix.MultiplyPoint3x4(mesh.vertices[i])));}Verify(a.id+" GPU agrees with browser and fixed anchors",error<.00002f&&rootError<.000003f,"error="+error+", roots="+rootError);RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);UnityEngine.Object.DestroyImmediate(positions);UnityEngine.Object.DestroyImmediate(masks);UnityEngine.Object.DestroyImmediate(probe);}
 static bool IsFixed(MapSharedPropsBuilder.AssetDto a,Material material,int i){if(a.motionWeights!=null)return a.motionWeights[i*2]==0&&a.motionWeights[i*2+1]==0;var b=material.GetVector("_PineBand");return a.positions[i*3+1]<=b.x||(a.id=="pine"&&a.uv[i*2+1]<=.5f);}
 static void Capture(Camera camera,string output,string name){var rt=new RenderTexture(1280,800,24);rt.Create();camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(1280,800,TextureFormat.RGBA32,false);im.ReadPixels(new Rect(0,0,1280,800),0,0);im.Apply();File.WriteAllBytes(Path.Combine(output,name),im.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(im);}
}
